import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';

const file = process.argv[2];
const doc = JSON.parse(readFileSync(file, 'utf8'));
delete doc.integrity;

const canonical = (value) => {
	if (Array.isArray(value)) return value.map(canonical);
	if (value && typeof value === 'object') {
		return Object.fromEntries(
			Object.keys(value)
				.sort()
				.map((key) => [key, canonical(value[key])]),
		);
	}
	return value;
};

const digest = createHash('sha256').update(JSON.stringify(canonical(doc))).digest('hex');
doc.integrity = { algorithm: 'sha256', canonicalDigest: digest };
writeFileSync(file, `${JSON.stringify(canonical(doc), null, 1)}\n`);
console.log(digest);

